    {
      "day_number": "number",
      "current_city": "string",
      "accommodation": {
        "name": "string",
        "price_per_night": "number"
      },
      "activities": [
        {
          "time_slot": "string",
          "type": "string (e.g., travel_intercity_public, travel_city, attraction, meal, hotel, buffer)",
          "details": {
            // The "details" object structure varies depending on the "type" field
          }
        }
      ]
    }
  ]
}


CRITICAL RULE - DO NOT TRANSLATE NAMES: You must preserve ALL entity names exactly as they appear in the input text. This includes hotel names, restaurant names, attraction names, station/airport names, and train/flight numbers. Copy them character-for-character from the input. Do NOT translate, transliterate, or modify any names in any way. For example, if the input contains "هوم إن للأعمال السفر" as a hotel name, the JSON output must contain exactly "هوم إن للأعمال السفر", NOT "ហូម អ៊ីន Business Travel".

ច្បាប់បំលែងសំខាន់

- អំពីវាលស្នាក់នៅ:
ប្រសិនបើការបញ្ចូល Accommodation គឺ "-", បន្ទាប់មិនត្រូវបញ្ចូលវាលស្នាក់នៅសម្រាប់ថ្ងៃនោះនៅក្នុង daily_plans នៃលទ្ធផល; បើមិនដូច្នោះទេ បំពេញវត្ថុស្នាក់នៅតាមរចនាសម្ព័ន្ធ។

អ្នកត្រូវអនុវត្តច្បាប់ខាងក្រោមនៅពេលបង្កើតវត្ថុ details:
   1. Price Extraction: តម្លៃទាំងអស់នៅក្នុងការបញ្ចូលដែលមាននិមិត្តសញ្ញារូបិយប័ណ្ណ និងឯកតា (ឧ. ￥650, ￥100/person) ត្រូវតែបំបែកជាលេខសុទ្ធ (ឧ. 650, 100)។
   2. Route Splitting: ផ្លូវទាំងអស់នៅក្នុងទ្រង់ទ្រាយ [origin] - [destination] ត្រូវតែបំបែកជាវាល from និង to។
   3. Structure of details for each activity type:
      travel_intercity_public:
         "details": { "mode": "flight/train", "number": "flight/train number", "from": "departure location", "to": "arrival location", "cost": "number" }
      travel_city:
         "details": { "from": "origin", "to": "destination", "distance": "distance", "duration": "duration", "cost": "number" }
      attraction:
         "details": { "name": "attraction name", "city": "attraction city", "cost": "number" }
      meal:
         "details": { "meal_type": "breakfast/lunch/dinner", "name": "restaurant name", "cost": "number" }
      hotel:
         "details": { "activity": "activity", "name": "hotel name" }
      buffer:
         "details": { "description": "activity description" }
